const std = @import("std");

// Theme preview: types, fields, strings and calls.
const Palette = struct {
    name: []const u8,
    count: u32 = 42,

    pub fn describe(self: Palette) void {
        std.debug.print("Theme: {s} ({d})\n", .{ self.name, self.count });
    }
};

pub fn main() void {
    const palette = Palette{ .name = "Maru" };
    if (palette.count > 0) palette.describe();
}

