import React from "react";

// Theme preview: tags, attributes, types and expressions.
type Props = { title: string; count?: number };

export function ThemeCard({ title, count = 42 }: Props) {
  const enabled = count > 0;
  return (
    <section className="theme-card" data-active={enabled}>
      <h2>{title}</h2>
      <button disabled={!enabled} onClick={() => alert(title)}>
        Preview {count} colors
      </button>
    </section>
  );
}

